# balance correct letters across A–D for single-answer Qs (swap correct option into a rotating target slot)
_t=0
for k,(s,stem,opts,ans,why) in enumerate(Q):
    if len(ans)==1 and len(opts)==4:
        tgt=[0,3,2,1][_t%4]; _t+=1
        c=ans[0]; opts=opts[:]; opts[c],opts[tgt]=opts[tgt],opts[c]
        Q[k]=(s,stem,opts,[tgt],why)
    elif len(ans)>1:
        import random
        idx=list(range(len(opts))); random.Random(k*7+3).shuffle(idx)
        Q[k]=(s,stem,[opts[j] for j in idx],sorted(idx.index(a) for a in ans),why)
# build
rows=[];sec=None
for i,(s,stem,opts,ans,why) in enumerate(Q,1):
    if s!=sec:
        rows.append(f'<div class="note" style="margin-top:14px"><b>{E(s)}</b></div>');sec=s
    m=len(ans)>1
    ob=''.join(f'<button class="opt">{chr(65+j)}. {E(o)}</button>' for j,o in enumerate(opts))
    rows.append(f'<div class="q" data-a="{json.dumps(ans)}" data-m="{int(m)}"><h3><span>Q{i}</span>{E(stem)}</h3>{ob}{"<button class=chk>Check ✓</button>" if m else ""}<div class="why">✅ <b>{", ".join(chr(65+a) for a in ans)}</b> · {E(why)}</div></div>')
